package matrix

import (
	"errors"
	"strconv"
	"strings"
)

// Matrix is a rectangular grid of numbers.
type Matrix *matrix

type matrix struct {
	rows [][]int
}

// New creates a Matrix from a string.
func New(s string) (Matrix, error) {
	if s == "" {
		return nil, errors.New("empty matrix")
	}
	lines := strings.Split(s, "\n")
	m := &matrix{}
	for _, line := range lines {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			return nil, errors.New("empty row")
		}
		row := make([]int, len(fields))
		for i, f := range fields {
			n, err := strconv.Atoi(f)
			if err != nil {
				return nil, err
			}
			row[i] = n
		}
		if len(m.rows) > 0 && len(row) != len(m.rows[0]) {
			return nil, errors.New("uneven rows")
		}
		m.rows = append(m.rows, row)
	}
	return m, nil
}

// Rows returns the rows of the matrix.
func (m Matrix) Rows() [][]int {
	rows := make([][]int, len(m.rows))
	for i, row := range m.rows {
		rows[i] = append([]int(nil), row...)
	}
	return rows
}

// Cols returns the columns of the matrix.
func (m Matrix) Cols() [][]int {
	cols := make([][]int, len(m.rows[0]))
	for _, row := range m.rows {
		for j, v := range row {
			cols[j] = append(cols[j], v)
		}
	}
	return cols
}

// Set sets the value at the given row and column.
func (m Matrix) Set(row, col, val int) bool {
	if row < 0 || row >= len(m.rows) || col < 0 || col >= len(m.rows[row]) {
		return false
	}
	m.rows[row][col] = val
	return true
}
