package matrix

import (
	"errors"
	"strconv"
	"strings"
)

// Matrix is a rectangular grid of integers.
type Matrix *matrix

type matrix struct {
	rows [][]int
}

var (
	errEmpty   = errors.New("matrix is empty")
	errEmptyRow = errors.New("row is empty")
	errUneven  = errors.New("rows have uneven lengths")
)

// New creates a Matrix from a string. Each line is a row, and fields on a
// line are whitespace-separated integers.
func New(s string) (Matrix, error) {
	if s == "" {
		return nil, errEmpty
	}
	m := &matrix{}
	for _, line := range strings.Split(s, "\n") {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			return nil, errEmptyRow
		}
		row := make([]int, len(fields))
		for i, f := range fields {
			n, err := strconv.ParseInt(f, 10, 64)
			if err != nil {
				return nil, err
			}
			row[i] = int(n)
		}
		if len(m.rows) > 0 && len(row) != len(m.rows[0]) {
			return nil, errUneven
		}
		m.rows = append(m.rows, row)
	}
	return m, nil
